    agregar("G12-L1-10", CLASE_12, "L1", "Desviación intermitente del ángulo del variador de levas con retraso de respuesta.", "TECNICO", "marcha", "desviacion_angulo_variador_levas", "", "", "SI", "NO", "", "L1 técnico de retardo en variador.")

    # --- L2 (15 casos) ---
    agregar("G12-L2-01", CLASE_12, "L2", "El motor funciona perfecto en frío, pero al calentar y llegar a un semáforo el ralentí oscila entre 500 y 900 rpm y suena un traqueteo en el solenoide VVT.", "COTIDIANO", "ralenti_caliente", "ralenti_oscilante_caliente|traqueteo_solenoide_vvt", "falla_en_frio", "", "NO", "SI", "Cuerpo de aceleracion o valvula IAC sucia", "L2 VVT atascado en caliente vs IAC.")
    agregar("G12-L2-02", CLASE_12, "L2", "Código P0011 de sincronización avanzada en banco 1; el carro pierde agilidad arriba de 3000 rpm y el solenoide de levas tiene lodo de aceite pegado.", "TALLER", "alta_rpm", "dtc_p0011|solenoide_vvt_con_lodo|perdida_potencia_alta", "cadena_suelta", "P0011", "NO", "SI", CLASE_11, "L2 código P0011 con solenoide sucio vs cadena.")
    agregar("G12-L2-03", CLASE_12, "L2", "Al pisar a fondo el auto no da el segundo empuje de aceleración y se siente amarrado, consumiendo un 20 por ciento más de gasolina en autopista.", "COTIDIANO", "aceleracion_fondo", "falta_empuje_vvt|consumo_elevado", "humo_negro", "", "NO", "SI", "Inyectores sucios o filtro de combustible obstruido", "L2 falta de avance de levas en alta vs inyección.")
    agregar("G12-L2-04", CLASE_12, "L2", "El piñón de sincronización variable suena tac-tac-tac fuerte al soltar el pedal del acelerador por pérdida de presión hidráulica interna del engranaje.", "TALLER", "desaceleracion", "pinon_vvt_suena_tac_tac|perdida_presion_interna", "biela_golpeando", "", "NO", "SI", "Baja presion de aceite o bomba de aceite defectuosa", "L2 ruido de piñón desfasador vs cojinete de biela.")
    agregar("G12-L2-05", CLASE_12, "L2", "Hola maestro, el escáner bota P0012 por árbol de levas retrasado. La cadena de tiempo está tensa y en sus marcas pero la válvula de aceite del VVT no conmuta.", "WHATSAPP", "diagnostico", "dtc_p0012|cadena_tensa_en_marcas|valvula_vvt_no_conmuta", "cadena_fuera_punto", "P0012", "NO", "SI", CLASE_11, "L2 marcas de distribución OK descartan cadena saltada.")
    agregar("G12-L2-06", CLASE_12, "L2", "En subidas largas el motor se queda sin avance de válvulas encendiendo el check con DTC P0014, desapareciendo el tironeo cuando se baja a ralentí.", "TECNICO", "subida_sostenida", "dtc_p0014|sin_avance_valvulas|desaparece_en_ralenti", "misfire_cilindro", "P0014", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L2 VVT escape P0014 bajo esfuerzo vs misfire.")
    agregar("G12-L2-07", CLASE_12, "L2", "El microfiltro de malla del solenoide VVT ubicado en la culata estaba completamente tapado de sedimentos de aceite viejo, bloqueando el avance.", "TALLER", "inspeccion_filtro_vvt", "filtro_vvt_malla_tapado|bloqueo_avance", "falla_electrica_arnes", "", "NO", "NO", "", "L2 coladera de solenoide VVT tupida.")
    agregar("G12-L2-08", CLASE_12, "L2", "El carro calienta normal pero tiembla en parado y tira codigo P0011. El aceite tiene su nivel pero es un 20W-50 grueso que no deja cargar al variador.", "ERROR_ORTOGRAFICO", "ralenti_caliente", "dtc_p0011|aceite_muy_grueso_bloquea_vvt", "nivel_bajo_aceite", "P0011", "NO", "SI", "Baja presion de aceite o bomba de aceite defectuosa", "L2 viscosidad inadecuada bloquea sistema VVT con ortografía informal.")
    agregar("G12-L2-09", CLASE_12, "L2", "Sistema Valvetronic entra en modo degradado de emergencia limitando la velocidad a 60 km/h; el motor eléctrico de la excéntrica tiene resistencia elevada.", "TECNICO", "modo_emergencia", "valvetronic_modo_degradado|motor_excentrica_resistencia_alta", "falla_pedal_acelerador", "", "NO", "NO", "", "L2 Valvetronic en modo de emergencia.")
    agregar("G12-L2-10", CLASE_12, "L2", "Al desacelerar tras rodar a 80 km/h el motor casi se apaga y cabecea bruscamente porque el árbol de levas se queda pegado en posición avanzada.", "COTIDIANO", "desaceleracion_brusca", "cabeceo_al_desacelerar|arbol_pegado_en_avance", "falla_freno_motor", "", "NO", "SI", "Cuerpo de aceleracion o valvula IAC sucia", "L2 retorno lento de avance VVT causa ahogo al frenar.")
    agregar("G12-L2-11", CLASE_12, "L2", "Buenas, cambié de aceite a uno sintético limpio y ahora la aguja de potencia sube con vacíos arriba de 3500 rpm con la luz de motor prendida.", "WHATSAPP", "alta_rpm", "vacios_potencia_3500rpm|testigo_motor", "falla_embrague", "", "NO", "NO", "", "L2 desfasador VVT no sostiene presión tras cambio de fluido.")
    agregar("G12-L2-12", CLASE_12, "L2", "El actuador del árbol de levas presenta juego radial interno y fugas de presión de aceite por el retén frontal, provocando golpeteo al regular.", "TALLER", "ralenti", "juego_radial_actuador_vvt|fuga_presion_reten", "golpeteo_valvulas", "", "NO", "NO", "", "L2 desgaste interno de piñón variador.")
    agregar("G12-L2-13", CLASE_12, "L2", "Se midió la resistencia del solenoide VVT arrojando 45 ohms cuando la especificación OEM es de 7 a 12 ohms, indicando bobinado recalentado.", "TECNICO", "prueba_electrica", "resistencia_vvt_45_ohms_fuera_rango", "falla_computadora", "", "NO", "NO", "", "L2 solenoide VVT degradado eléctricamente.")
    agregar("G12-L2-14", CLASE_12, "L2", "El auto pierde pique en pendientes pronunciadas donde antes trepaba en cuarta; la computadora no logra modificar el cruce de válvulas en demanda de carga.", "COTIDIANO", "subida_carga", "falta_pique_subida|sin_modificacion_cruce_valvulas", "falla_bomba_gasolina", "", "NO", "SI", "Bomba de gasolina quemada o con baja presion", "L2 falta de avance variable en pendiente vs bomba de gasolina.")
    agregar("G12-L2-15", CLASE_12, "L2", "Ralentí muy inestable solo con motor caliente acompañado de DTC P0011; al desconectar la ficha eléctrica del solenoide VVT el motor empareja de inmediato.", "TALLER", "desconexion_prueba", "dtc_p0011|desconexion_vvt_empareja_motor", "falla_bujia", "P0011", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L2 prueba de desconexión directa descarta misfire.")

    # --- L3 (15 casos) ---
    agregar("G12-L3-01", CLASE_12, "L3", "Escáner en datos en vivo grafica 'Desired Camshaft Position' en 35 grados de avance a 3200 rpm mientras que 'Actual Camshaft Position' se queda estancado en 4 grados. Se registra DTC P0011 permanente. La presión de aceite de motor está en 45 psi correcta y la cadena de tiempo está perfectamente calada, comprobándose solenoide OCV trabado por carbón.", "TECNICO", "datos_en_vivo_3200rpm", "dtc_p0011|desired_35_actual_4_grados|solenoide_ocv_trabado", "cadena_saltada|baja_presion_aceite", "P0011", "NO", "SI", CLASE_11, "L3 telemetría de Target vs Actual en escáner descarta cadena.")
    agregar("G12-L3-02", CLASE_12, "L3", "El vehículo presenta ralentí inestable y cabeceo severo al detenerse tras 20 minutos de autopista con código P0012. Al desmontar la válvula de control de aceite VVT se halló el émbolo interno agarrotado por barniz de aceite degradado. Al suministrar 12V directos en banco de prueba el actuador no se desplaza ni emite clic.", "TALLER", "banco_prueba_vvt", "dtc_p0012|embolo_ocv_agarrotado_barniz|sin_desplazamiento_12v", "falla_iac", "P0012", "NO", "SI", "Cuerpo de aceleracion o valvula IAC sucia", "L3 prueba en banco de válvula OCV atascada.")
    agregar("G12-L3-03", CLASE_12, "L3", "En aceleración plena por encima de 4000 rpm el motor pierde rendimiento y emite DTC P0014 en levas de escape. Al medir con osciloscopio la señal PWM de control proveniente de la ECU tiene ciclo de trabajo del 80%, pero el árbol de levas responde con 600 milisegundos de retraso por desgaste interno en las paletas del piñón variador.", "TECNICO", "alta_rotacion_4000rpm", "dtc_p0014|pwm_80_porciento|retraso_600ms_paletas_pinon", "falla_computadora", "P0014", "NO", "NO", "", "L3 retardo de 600 ms por fuga en paletas de piñón desfasador.")
    agregar("G12-L3-04", CLASE_12, "L3", "Traqueteo metálico tipo cascabeleo al desacelerar de 3000 a 1000 rpm en caliente. Se desmontó el engranaje del variador VVT de admisión encontrándose el pasador de bloqueo interno desgastado y con holgura en su alojamiento, impidiendo que el engranaje enganche en posición cero al caer las revoluciones.", "TALLER", "desaceleracion", "pasador_bloqueo_vvt_desgastado|cascabeleo_al_desacelerar", "ruido_cadena_distribucion", "", "NO", "SI", CLASE_11, "L3 pasador de traba de engranaje VVT con holgura.")
    agregar("G12-L3-05", CLASE_12, "L3", "Hola maestro, el auto pierde fuerza arriba y prende el check con código P0016. Se revisaron las marcas mecánicas de calado con regla de fábrica y están exactas al milímetro. Lo que fallaba era el piñón de levas VVT que se trabó internamente y no gira sobre su eje.", "WHATSAPP", "diagnostico_calado", "dtc_p0016|marcas_calado_exactas|pinon_vvt_trabado_eje", "cadena_estirada", "P0016", "NO", "SI", CLASE_11, "L3 calado perfecto descarta cadena y señala piñón VVT.")
    agregar("G12-L3-06", CLASE_12, "L3", "Vehículo alemán con motor Valvetronic presenta código 2A67 y entra en modo de emergencia sin aceleración. El motor de accionamiento del eje excéntrico arroja cortocircuito a masa en su devanado interno y el sensor de ángulo de excéntrica no reconoce la posición de tope mínimo.", "TECNICO", "modo_emergencia_valvetronic", "valvetronic_dtc_2a67|motor_excentrico_corto|sin_tope_minimo", "falla_cuerpo_aceleracion", "", "NO", "SI", "Cuerpo de aceleracion o valvula IAC sucia", "L3 falla de servomotor excéntrico Valvetronic.")
    agregar("G12-L3-07", CLASE_12, "L3", "El motor tironea a 2800 rpm y el consumo subió a 14 litros cada 100 km. Al retirar el perno pasante del solenoide de distribución variable se encontró el tamiz de malla filtrante roto con partículas de carbón que trabaron la corredera en avance máximo continuo.", "TALLER", "inspeccion_solenoide", "tamiz_vvt_roto|corredera_trabada_avance_maximo", "inyectores_goteando", "", "NO", "SI", "Inyectores sucios o filtro de combustible obstruido", "L3 tamiz de filtro VVT roto con corredera trabada.")
    agregar("G12-L3-08", CLASE_12, "L3", "Prueba dinámica en carretera: a 100 km/h sostenidos se genera DTC P0011 intermitente. La señal del sensor de árbol de levas es nítida pero el desfase respecto al cigüeñal oscila erráticamente 8 grados por encima del objetivo por fuga de presión a través de los anillos de estanqueidad de la tapa de levas.", "TECNICO", "carretera_dinamica", "dtc_p0011|oscilacion_erratica_8_grados|anillos_estanqueidad_levas", "sensor_cmp_defectuoso", "P0011", "NO", "NO", "", "L3 fuga en anillos de teflón de lubricación de árbol.")
    agregar("G12-L3-09", CLASE_12, "L3", "El carro pierde potencia en subida y en mínimo tiembla en caliente arrojando P0012. El mecanico le midio la resistencia a la electrovalvula VVT y dio 50 ohmios cuando debe tener 8 ohmios. Al ponerle solenoide nuevo emparejo el motor de una.", "ERROR_ORTOGRAFICO", "subida_y_ralenti", "dtc_p0012|resistencia_vvt_50_ohmios|solenoide_nuevo_soluciona", "falla_bujias", "P0012", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L3 resistencia 50 ohms en solenoide con ortografía informal.")
    agregar("G12-L3-10", CLASE_12, "L3", "DTC P0026 referente a circuito de válvula solenoide de admisión banco 1. Prueba de osciloscopio en el conector de la válvula muestra señal de control con modulación de ancho de pulso normal pero consumo de corriente de 0 amperios por bobina cortada en el solenoide OCV.", "TECNICO", "diagnostico_electrico", "dtc_p0026|senal_pwm_ok|consumo_0_amperios_bobina_abierta", "falla_cableado_ecu", "", "NO", "NO", "", "L3 análisis osciloscópico de corriente en OCV.")
    agregar("G12-L3-11", CLASE_12, "L3", "El auto arranca bien y camina suave en frío pero a los 15 minutos de tráfico tiembla como si fallara una bujía y prende el check con P0011. Se cambiaron bobinas y bujías sin cambio alguno; la falla era el variador VVT que al licuarse el aceite se queda trabado en avance.", "TALLER", "post_cambio_bobinas", "dtc_p0011|persiste_tras_bobinas_bujias|variador_trabado_caliente", "falla_chispa", "P0011", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L3 persistencia tras cambio de bobinas descarta encendido.")
    agregar("G12-L3-12", CLASE_12, "L3", "Presión de aceite general marca 40 psi pero en el conducto específico de alimentación al piñón VVT cae a 10 psi por obturación del tornillo banjo con filtro integrado en la culata, provocando código P0012 por retardo severo de levas.", "TECNICO", "medicion_puerto_vvt", "dtc_p0012|presion_puerto_vvt_10psi|tornillo_banjo_obstruido", "bomba_aceite_defectuosa", "P0012", "NO", "SI", "Baja presion de aceite o bomba de aceite defectuosa", "L3 caída de presión localizada en tornillo banjo.")
    agregar("G12-L3-13", CLASE_12, "L3", "En desaceleración rápida el motor cae a 450 rpm y se apaga registrando código P0011. La electroválvula de control no retorna a su posición de reposo debido a rayaduras en el cilindro de la corredera producidas por contaminación metálica en el aceite.", "TALLER", "desaceleracion_apagado", "dtc_p0011|apagado_450rpm|corredera_ocv_rayada", "falla_cuerpo_mariposa", "P0011", "NO", "SI", "Cuerpo de aceleracion o valvula IAC sucia", "L3 corredera rayada por viruta no retorna a cero.")
    agregar("G12-L3-14", CLASE_12, "L3", "Hola maestro, el carro no tiene pique en alta y se siente frenado cuando paso de 3000 vueltas. En el taller revisaron la distribución y la cadena está perfecta, pero al medir la válvula VVT no abre el paso de aceite y el árbol se queda sin avance.", "WHATSAPP", "alta_rotacion", "sin_pique_alta_3000rpm|cadena_perfecta|valvula_vvt_no_abre_paso", "cadena_saltada", "", "NO", "SI", CLASE_11, "L3 cadena perfecta descarta distribución y confirma VVT.")
    agregar("G12-L3-15", CLASE_12, "L3", "Inspección de actuador VVT electromagnético en banco: el núcleo móvil presenta magnetización residual y deformación en el resorte de retroceso, provocando que el tiempo de recuperación de sincronía exceda los 1.2 segundos y active el DTC P0012.", "TECNICO", "prueba_banco_actuador", "dtc_p0012|magnetizacion_residual|tiempo_retorno_excede_1_2s", "falla_sensor_posicion", "P0012", "NO", "NO", "", "L3 retardo de 1.2 segundos por resorte deformado.")

