    # --- L1 (10 casos) ---
    agregar("G14-L1-01", CLASE_14, "L1", "Se prendió la luz EPC en el tablero y el carro perdió fuerza de golpe.", "COTIDIANO", "aceleracion_autopista", "luz_epc|perdida_fuerza_subita", "", "", "SI", "NO", "", "L1 testigo EPC y corte súbito de turbo.")
    agregar("G14-L1-02", CLASE_14, "L1", "Hola, al acelerar fuerte en tercera se me corta la potencia y no pasa de 80.", "WHATSAPP", "tercera_marcha", "corte_potencia_tercera|no_pasa_80", "", "", "SI", "NO", "", "L1 corte de potencia en aceleración.")
    agregar("G14-L1-03", CLASE_14, "L1", "Siento un cascabeleo metálico al soltar el acelerador en el motor turbo.", "COTIDIANO", "desaceleracion", "cascabeleo_metalico_soltar_acelerador", "", "", "SI", "NO", "", "L1 cascabeleo de varilla/wastegate suelta.")
    agregar("G14-L1-04", CLASE_14, "L1", "El carro entra en modo de emergencia cuando le exijo en subida.", "TALLER", "subida_exigida", "modo_emergencia_subida", "", "", "SI", "NO", "", "L1 limp mode bajo carga en subida.")
    agregar("G14-L1-05", CLASE_14, "L1", "El turbo a veces sopla y a veces se queda completamente muerto.", "COTIDIANO", "marcha_variable", "turbo_sopla_intermitente", "", "", "SI", "NO", "", "L1 comportamiento errático de presión de turbo.")
    agregar("G14-L1-06", CLASE_14, "L1", "Aparece un código de sobrepresión o baja presión de turbo en el tablero.", "TECNICO", "diagnostico", "codigo_presion_turbo", "", "", "SI", "NO", "", "L1 reporte genérico de presión de turbo.")
    agregar("G14-L1-07", CLASE_14, "L1", "Apago el motor y lo vuelvo a prender y la fuerza regresa normal.", "WHATSAPP", "reinicio_motor", "reinicio_restaura_potencia", "", "", "SI", "NO", "", "L1 reinicio limpia transitoriamente el limp mode.")
    agregar("G14-L1-08", CLASE_14, "L1", "El auto tironea en alta y la varilla del turbo vibra con un sonido a lata.", "TALLER", "alta_rpm", "tironeo_alta|varilla_turbo_vibra", "", "", "SI", "NO", "", "L1 vibración de varilla de actuador.")
    agregar("G14-L1-09", CLASE_14, "L1", "Se prende el EPC y se queda sin turbo cuando paso un camion en pista.", "ERROR_ORTOGRAFICO", "adelantamiento", "epc_adelantamiento|sin_turbo", "", "", "SI", "NO", "", "L1 corte en sobrepaso con error ortográfico.")
    agregar("G14-L1-10", CLASE_14, "L1", "Desviación entre la presión de soplado especificada y la real del turbocompresor.", "TECNICO", "plena_carga", "desviacion_presion_soplado_turbo", "", "", "SI", "NO", "", "L1 técnico de divergencia de sobrealimentación.")

    # --- L2 (15 casos) ---
    agregar("G14-L2-01", CLASE_14, "L2", "En autopista al pisar a fondo en cuarta se prende el testigo EPC y el carro entra en modo de emergencia; apago y prendo el carro y vuelve a acelerar normal.", "COTIDIANO", "autopista_cuarta", "testigo_epc_acelerar|modo_emergencia|resetea_al_apagar", "falla_permanente", "P0299", "NO", "NO", "", "L2 corte de turbo reseteable con llave con DTC P0299.")
    agregar("G14-L2-02", CLASE_14, "L2", "Se escucha un sonido de sonajero metálico constante en la caracola de escape del turbo al soltar el gas entre 2000 y 3000 rpm por holgura del actuador de la wastegate.", "TALLER", "desaceleracion_2000_3000rpm", "sonajero_wastegate_desacelerar|holgura_actuador", "ruido_interno_motor", "", "NO", "SI", CLASE_11, "L2 cascabeleo de wastegate vs cadena de distribución.")
    agregar("G14-L2-03", CLASE_14, "L2", "Código P0299 por baja presión de turbo; las mangueras de intercooler no tienen fugas ni están rotas pero la varilla del actuador electrónico está dura y atascada.", "TECNICO", "inspeccion_varilla", "dtc_p0299|mangueras_intercooler_sanas|varilla_actuador_atascada", "fuga_manguera_intercooler", "P0299", "NO", "SI", CLASE_15, "L2 varilla trabada con mangueras sanas descarta fuga de intercooler.")
    agregar("G14-L2-04", CLASE_14, "L2", "Hola, mi Golf TSI corta la potencia al pasar los 120 km/h y prende EPC. No hay silbido de fuga de aire en el motor, simplemente el turbo deja de empujar.", "WHATSAPP", "velocidad_120kmh", "epc_corte_120kmh", "silbido_fuga_aire", "P0299", "NO", "SI", CLASE_15, "L2 corte de turbo sin silbido de aire descarta fuga de manguera.")
    agregar("G14-L2-05", CLASE_14, "L2", "El actuador eléctrico del turbocompresor no completa el ajuste básico con el escáner marcando error de adaptación por límite de recorrido excedido.", "TECNICO", "ajuste_basico_escaner", "error_ajuste_basico_turbo|limite_recorrido_excedido", "falla_sensor_map", "", "NO", "NO", "", "L2 fallo de calibración básica de actuador de turbo.")
    agregar("G14-L2-06", CLASE_14, "L2", "Al exigir en subida se genera código P0234 de sobrepresión porque la compuerta de alivio wastegate no abre a tiempo para descargar los gases de escape.", "TALLER", "subida_exigida", "dtc_p0234_sobrepresion|wastegate_no_abre", "fuga_presion", "P0234", "NO", "SI", CLASE_15, "L2 sobrepresión P0234 por wastegate trabada cerrada.")
    agregar("G14-L2-07", CLASE_14, "L2", "El motor anda perfecto en uso urbano tranquilo, pero en el momento en que acelero rápido para adelantar salta el EPC y queda sin fuerza de turbo.", "COTIDIANO", "adelantamiento_brusco", "salto_epc_adelantamiento|sin_fuerza_turbo", "falla_en_baja", "", "NO", "NO", "", "L2 fallo exclusivo bajo solicitación de alta carga.")
    agregar("G14-L2-08", CLASE_14, "L2", "Mi carro Audi TFSI prende el EPC al acelerar fuerte y en el escaner sale P0299. Las mangueras del turbo estan bien apretadas y no se escucha soplo de aire.", "ERROR_ORTOGRAFICO", "aceleracion_fuerte", "dtc_p0299_audi|mangueras_apretadas|sin_soplo_aire", "manguera_rota_intercooler", "P0299", "NO", "SI", CLASE_15, "L2 P0299 sin soplo con error ortográfico.")
    agregar("G14-L2-09", CLASE_14, "L2", "Inspección mecánica demostró holgura de 2 milímetros en el buje del eje de la wastegate, provocando pérdida de cierre hermético y presión tardía de soplado.", "TALLER", "inspeccion_buje", "holgura_2mm_buje_wastegate|cierre_no_hermetico", "falla_paletas_compresor", "", "NO", "NO", "", "L2 holgura de 2 mm en buje de wastegate.")
    agregar("G14-L2-10", CLASE_14, "L2", "DTC P2563 referente a señal fuera de rango del sensor de posición del actuador de la geometría variable en motor 2.0 TDI diésel.", "TECNICO", "diagnostico_vgt", "dtc_p2563_posicion_vgt|senal_fuera_rango", "falla_inyector_diesel", "P2563", "NO", "NO", "", "L2 código P2563 de sensor de posición VGT.")
    agregar("G14-L2-11", CLASE_14, "L2", "Buenas maestro, el carro acelera bien hasta medio pedal, pero si piso a fondo entra en modo tortuga y prende EPC. Lo apago cinco minutos y vuelve a acelerar.", "WHATSAPP", "aceleracion_plena", "modo_tortuga_fondo|epc_prendido|apaga_y_resetea", "falla_bomba_gasolina", "", "NO", "SI", "Bomba de gasolina quemada o con baja presion", "L2 limp mode transitorio vs bomba de gasolina.")
    agregar("G14-L2-12", CLASE_14, "L2", "El motor eléctrico del actuador de turbo presenta resistencia térmica; funciona frío pero al calentar la carcasa se bloquea mecánicamente.", "TALLER", "motor_caliente", "actuador_turbo_bloquea_en_caliente", "falla_en_frio", "", "NO", "NO", "", "L2 traba térmica en actuador eléctrico de turbo.")
    agregar("G14-L2-13", CLASE_14, "L2", "Al pisar el acelerador la presión de turbo solicitada por ECU es 1.3 bar pero el sensor MAP solo registra 0.6 bar estancado por varilla atascada.", "TECNICO", "plena_carga", "presion_solicitada_1_3_real_0_6|varilla_atascada", "fuga_conducto_admision", "P0299", "NO", "SI", CLASE_15, "L2 divergencia MAP 1.3 vs 0.6 bar por varilla atascada.")
    agregar("G14-L2-14", CLASE_14, "L2", "El auto pierde potencia de repente y no responde el turbo; el varillaje que conecta el motor eléctrico con la turbina está oxidado y agarrotado.", "COTIDIANO", "marcha", "varillaje_oxidado_agarrotado|sin_respuesta_turbo", "falla_ignicion", "", "NO", "NO", "", "L2 varillaje oxidado mecánicamente trabado.")
    agregar("G14-L2-15", CLASE_14, "L2", "Se genera código P0234 por sobrepresión de soplado; el motor tironea con violencia en tercera al llegar a 3500 rpm por cierre permanente de compuerta.", "TALLER", "3500rpm_tercera", "dtc_p0234_sobrepresion|tironeo_violento_3500rpm", "falla_caja", "P0234", "NO", "NO", "", "L2 tironeo violento por sobrepresión descontrolada.")

    # --- L3 (15 casos) ---
    agregar("G14-L3-01", CLASE_14, "L3", "En prueba de carretera bajo aceleración a fondo en 4ta marcha a 3500 rpm se enciende testigo EPC y el motor entra en modo de emergencia. Escáner reporta DTC P0299 (Underboost). La presión especificada de turbo es de 2100 mbar mientras que la real no supera los 1350 mbar. La prueba de humo en circuito de intercooler descartó fugas y se constató que la varilla del actuador de la wastegate presenta atasco mecánico por óxido en el pivote.", "TECNICO", "autopista_4ta_3500rpm", "dtc_p0299|presion_2100_vs_1350mbar|varilla_wastegate_atascada_oxido", "fuga_intercooler_humo_negativo", "P0299", "NO", "SI", CLASE_15, "L3 prueba de humo negativa descarta intercooler y confirma atasco de varilla.")
    agregar("G14-L3-02", CLASE_14, "L3", "Vehículo 1.8 TSI presenta cascabeleo metálico audible en desaceleración entre 2800 y 1800 rpm. Inspección en elevador desmontando el catalizador reveló holgura radial de 2.5 mm en el buje de la compuerta wastegate de la caracola de escape, impidiendo el cierre plano hermético y generando código P0299 intermitente sin ruidos en la cadena de distribución.", "TALLER", "desaceleracion_elevador", "holgura_2_5mm_buje_wastegate|dtc_p0299_intermitente", "ruido_cadena_distribucion", "P0299", "NO", "SI", CLASE_11, "L3 inspección interna de wastegate descarta cadena de distribución.")
    agregar("G14-L3-03", CLASE_14, "L3", "Al acelerar a plena carga en autopista se activa testigo EPC y código P0234 de sobrepresión. El manómetro de turbo registra pico de 1.8 bar superando el límite de seguridad de 1.2 bar. El actuador eléctrico V465 no logra retornar a la posición abierta debido a deformación interna en el sinfín de plástico del servomotor.", "TECNICO", "autopista_plena_carga", "dtc_p0234_overboost|pico_1_8bar|sinfin_plastico_v465_deformado", "falla_sensor_map", "P0234", "NO", "NO", "", "L3 engranaje sinfín de actuador V465 barrido.")
    agregar("G14-L3-04", CLASE_14, "L3", "El auto corta potencia abruptamente en adelantamientos a 100 km/h encendiendo EPC. En escáner el voltaje del sensor de posición del actuador de turbo marca 4.8V fijo fuera de tolerancia (rango válido 3.5V a 4.2V en reposo). Al intentar realizar el ajuste básico del canal de sobrealimentación el proceso es abortado por la ECU.", "TECNICO", "adelantamiento_100kmh", "epc_corte_100kmh|voltaje_actuador_4_8v_invalido|ajuste_basico_abortado", "falla_pedal_acelerador", "", "NO", "NO", "", "L3 voltaje fuera de rango 4.8V y ajuste básico abortado.")
    agregar("G14-L3-05", CLASE_14, "L3", "Hola maestro, tengo un Seat León TSI. En subida rápida se prende la luz EPC y el carro se muere, no acelera nada y tengo que orillarme, apagar el motor y prenderlo para que vuelva a jalar. En el taller revisaron y dicen que el actuador del turbo se queda pegado cuando calienta.", "WHATSAPP", "subida_rapida", "epc_se_muere_subida|apagar_y_prender_restaura|actuador_turbo_pegado_caliente", "falla_bomba_gasolina", "", "NO", "SI", "Bomba de gasolina quemada o con baja presion", "L3 relato WhatsApp de limp mode térmico de actuador.")
    agregar("G14-L3-06", CLASE_14, "L3", "Motor 2.0 TDI diésel genera DTC P2563 y testigo de espiral de precalentamiento parpadeando bajo carga. Se conectó bomba de vacío manual (Mityvac) al actuador neumático de geometría variable comprobándose que la membrana retiene 20 inHg pero la varilla no desplaza por carbón acumulado en los álabes variables de la turbina.", "TECNICO", "prueba_mityvac_vgt", "dtc_p2563|membrana_retiene_20inhg|alabes_vgt_trabados_carbon", "membrana_rota", "P2563", "NO", "NO", "", "L3 Mityvac retiene vacío confirmando traba mecánica en álabes VGT.")
    agregar("G14-L3-07", CLASE_14, "L3", "El cliente se queja de un cascabeleo tipo lámina suelta al soltar el acelerador y pérdida de pique. Se instaló clip de refuerzo de wastegate (anti-rattle clip) en la varilla del actuador eliminando el juego mecánico y restableciendo la respuesta inmediata del turbo sin cambiar mangueras de intercooler.", "TALLER", "instalacion_clip_wastegate", "sonajero_wastegate|clip_anti_rattle_soluciona|recupera_pique", "falla_mangueras_intercooler", "", "NO", "SI", CLASE_15, "L3 instalación de clip anti-rattle soluciona holgura mecánica.")
    agregar("G14-L3-08", CLASE_14, "L3", "DTC P0299 en motor 1.4 TSI. Al verificar con máquina de humo a 1 bar el circuito de admisión y mangueras de intercooler están 100% herméticos sin ninguna fuga. Al desacoplar la rótula del actuador eléctrico se comprobó que el brazo de la wastegate está trabado por herrumbre a medio abrir.", "TECNICO", "maquina_humo_1bar", "dtc_p0299|circuito_humo_100_hermetico|brazo_wastegate_trabado_medio_abrir", "fuga_intercooler", "P0299", "NO", "SI", CLASE_15, "L3 prueba de humo hermética confirma compuerta trabada.")
    agregar("G14-L3-09", CLASE_14, "L3", "Mi carro Audi corta el turbo en carretera y prende EPC arrojando P0299. Ya le revisaron todas las mangueras de aire y estan sanas. El mecanico le movio la varilla del turbo con la mano y esta dura trancada, no se mueve ni con alicate.", "ERROR_ORTOGRAFICO", "carretera_fondo", "dtc_p0299|mangueras_sanas|varilla_turbo_trancada_mano", "manguera_rajada", "P0299", "NO", "SI", CLASE_15, "L3 varilla trancada con mangueras sanas y error ortográfico.")
    agregar("G14-L3-10", CLASE_14, "L3", "En aceleración progresiva de 2000 a 4500 rpm el escáner muestra que la presión de sobrealimentación no sube de 0.4 bar relativo. El servomotor del actuador de turbo consume 1.8 amperios en reposo por motor eléctrico en cortocircuito parcial y el eje no ejecuta el autotesteo al dar contacto.", "TECNICO", "autotesteo_contacto", "boost_estancado_0_4bar|consumo_1_8a_reposo|sin_autotesteo", "falla_valvula_alivio_blowoff", "", "NO", "NO", "", "L3 servomotor con consumo excesivo y sin barrido de inicio.")
    agregar("G14-L3-11", CLASE_14, "L3", "Buenas tardes, el auto pierde potencia en autopista cuando quiero pasar a otro vehículo. Se prende la luz EPC y no pasa de 2500 rpm. Apago el contacto, saco la llave, vuelvo a encender y acelera bien un rato hasta que vuelvo a pisar a fondo.", "WHATSAPP", "autopista_rebase", "corte_epc_2500rpm|apagar_y_sacar_llave_resetea", "falla_caja_dsg", "", "NO", "NO", "", "L3 ciclo de llave limpia limp mode de sobrealimentación.")
    agregar("G14-L3-12", CLASE_14, "L3", "Registro de datos en tiempo real revela pico de sobrepresión de 2.3 bar absolutos a 3200 rpm seguido de corte abrupto por protección de motor con DTC P0234. La varilla del actuador no alcanza el tope de apertura máxima impidiendo evacuar el exceso de gases de escape hacia el catalizador.", "TECNICO", "corte_proteccion_p0234", "dtc_p0234|pico_2_3bar|sin_apertura_maxima_escape", "falla_sensor_map", "P0234", "NO", "NO", "", "L3 pico de sobrepresión 2.3 bar activa mapa de protección.")
    agregar("G14-L3-13", CLASE_14, "L3", "El vehículo ingresó con testigo EPC encendido y marcha en modo de emergencia. Se reemplazó el actuador electrónico de la wastegate por repuesto nuevo y se ejecutó la calibración guiada con escáner logrando voltaje de reposo de 3.85V. La presión de turbo se restableció en 1.1 bar en prueba de ruta.", "TALLER", "post_reemplazo_actuador", "reemplazo_actuador_nuevo|voltaje_3_85v_ok|boost_1_1bar_ruta", "dano_turbina", "", "NO", "NO", "", "L3 calibración a 3.85V normaliza presión a 1.1 bar.")
    agregar("G14-L3-14", CLASE_14, "L3", "Sonido de vibración metálica al desacelerar acompañado de pérdida de respuesta en baja. Se verificó con reloj comparador holgura axial de 1.8 mm en la articulación de la varilla de la wastegate. No se evidencian fugas de aceite en los sellos del turbo ni rozamiento de álabes.", "TALLER", "reloj_comparador_articulacion", "holgura_1_8mm_reloj_comparador|sin_fuga_aceite_sellos", "desgaste_eje_turbo", "", "NO", "SI", CLASE_15, "L3 reloj comparador 1.8 mm descarta daño interno de turbina.")
    agregar("G14-L3-15", CLASE_14, "L3", "Falla intermitente bajo temperatura extrema: tras 40 minutos en tráfico pesado el actuador de la compuerta de escape se dilata y queda trabado en 15% de apertura, activando código P0299 al salir a vía rápida. En frío la varilla se desplaza suavemente.", "TECNICO", "dilatacion_termica_trafico", "dtc_p0299|traba_15_porciento_en_caliente|varilla_suave_en_frio", "falla_valvula_n75", "P0299", "NO", "NO", "", "L3 dilatación térmica selectiva a 40 minutos en tráfico.")

    # =========================================================================
    # CLASE 15: Fuga en mangueras de intercooler o turbocompresor danado (40 casos)
    # =========================================================================

    # --- L1 (10 casos) ---
    agregar("G15-L1-01", CLASE_15, "L1", "Se escucha un silbido fuerte como de aire escapando cuando acelero.", "COTIDIANO", "aceleracion", "silbido_fuerte_aire_escapando", "", "", "SI", "NO", "", "L1 silbido de aire bajo presión.")
    agregar("G15-L1-02", CLASE_15, "L1", "El carro perdió fuerza de golpe y sopla como una aspiradora adelante.", "WHATSAPP", "aceleracion_carga", "soplo_aspiradora_adelante|perdida_fuerza", "", "", "SI", "NO", "", "L1 sonido de soplido frontal con pérdida de empuje.")
    agregar("G15-L1-03", CLASE_15, "L1", "Siento un aullido agudo como sirena de policía al subir las revoluciones.", "COTIDIANO", "subida_revoluciones", "aullido_sirena_policia", "", "", "SI", "NO", "", "L1 sonido de sirena de turbo dañado.")
    agregar("G15-L1-04", CLASE_15, "L1", "Bota bastante humo negro por el tubo de escape cuando piso el acelerador.", "TALLER", "aceleracion_fuerte", "humo_negro_aceleracion", "", "", "SI", "NO", "", "L1 humo negro por pérdida de aire medido.")
    agregar("G15-L1-05", CLASE_15, "L1", "Encontré una manguera gruesa del frente manchada de aceite negro y suelta.", "COTIDIANO", "inspeccion_visual", "manguera_gruesa_aceite_suelta", "", "", "SI", "NO", "", "L1 manguera de intercooler desacoplada con aceite.")
    agregar("G15-L1-06", CLASE_15, "L1", "Se escuchó un estallido como un globo reventado y el auto se quedó sin fuerza.", "WHATSAPP", "aceleracion_autopista", "estallido_globo_reventado|sin_fuerza", "", "", "SI", "NO", "", "L1 desacople o rotura súbita de manguera bajo presión.")
    agregar("G15-L1-07", CLASE_15, "L1", "El turbo silba exageradamente y el motor no tiene empuje en subida.", "TALLER", "subida", "turbo_silba_exagerado|sin_empuje_subida", "", "", "SI", "NO", "", "L1 silbido excesivo sin rendimiento.")
    agregar("G15-L1-08", CLASE_15, "L1", "Sopla mucho aire por el parachoques delantero cuando entra el turbo.", "ERROR_ORTOGRAFICO", "entrada_turbo", "soplo_aire_parachoques", "", "", "SI", "NO", "", "L1 soplido en intercooler con ortografía informal.")
    agregar("G15-L1-09", CLASE_15, "L1", "Bota humo azul espeso y se siente juego en la turbina del motor.", "TALLER", "marcha", "humo_azul_espeso|juego_turbina", "", "", "SI", "NO", "", "L1 sello de turbo roto con humo azul.")
    agregar("G15-L1-10", CLASE_15, "L1", "Fuga masiva de aire comprimido en el circuito de sobrealimentación bajo carga.", "TECNICO", "bajo_carga", "fuga_masiva_aire_comprimido", "", "", "SI", "NO", "", "L1 técnico de pérdida de aire comprimido.")

    # --- L2 (15 casos) ---
    agregar("G15-L2-01", CLASE_15, "L2", "Al acelerar a más de 2000 rpm se escucha un fuerte soplido de aire a presión bajo el capó, el carro se queda sin potencia y empieza a botar humo negro por el escape.", "COTIDIANO", "aceleracion_2000rpm", "soplido_aire_presion|perdida_potencia|humo_negro", "humo_blanco", "P0299", "NO", "SI", CLASE_14, "L2 manguera rajada con soplido y humo negro vs actuador.")
    agregar("G15-L2-02", CLASE_15, "L2", "El turbocompresor emite un sonido agudo de sirena de policía al acelerar en vacío y la turbina presenta juego axial excesivo rozando contra la caracola.", "TALLER", "aceleracion_vacio", "aullido_sirena_policia|juego_axial_roce_caracola", "fuga_mangueras", "", "NO", "NO", "", "L2 turbo dañado con rozamiento de álabes.")
    agregar("G15-L2-03", CLASE_15, "L2", "La manguera de salida del intercooler tiene una raja longitudinal de 5 cm cubierta de aceite por donde escapa todo el aire de soplado al pisar el pedal.", "TALLER", "plena_carga", "manguera_intercooler_rajada_5cm|aceite_y_escape_aire", "falla_bomba_gasolina", "", "NO", "SI", "Bomba de gasolina quemada o con baja presion", "L2 manguera rajada 5 cm visible vs bomba de gasolina.")
    agregar("G15-L2-04", CLASE_15, "L2", "Código P0299 por baja presión de turbo; al acelerar se escucha un silbido continuo delante y la varilla del actuador de la wastegate se mueve perfectamente.", "TECNICO", "aceleracion_marcha", "dtc_p0299|silbido_aire_delantero|varilla_wastegate_mueve_bien", "actuador_turbo_trabado", "P0299", "NO", "SI", CLASE_14, "L2 silbido de fuga con actuador funcionando correctamente.")
    agregar("G15-L2-05", CLASE_15, "L2", "Hola maestro, sentí un estruendo como un tiro en la Panamericana y el carro se quedó sin fuerza botando humo negro y soplando aire como loco.", "WHATSAPP", "autopista_acelerada", "estruendo_desacople|humo_negro|soplido_loco", "falla_motor_electrico", "", "NO", "NO", "", "L2 manguera de intercooler reventada en autopista.")
    agregar("G15-L2-06", CLASE_15, "L2", "El panal del intercooler tiene una fisura en el tanque plástico inferior producida por un golpe de piedra y silba fuerte cada vez que entra la turbina.", "COTIDIANO", "marcha", "fisura_tanque_intercooler|silbido_fuerte_boost", "falla_radiador_agua", "", "NO", "SI", "Fuga en mangueras de refrigerante o radiador picado", "L2 intercooler perforado vs radiador de refrigerante.")
    agregar("G15-L2-07", CLASE_15, "L2", "Humo azul abundante por el escape al acelerar y el nivel de aceite bajó un litro en 300 km; el eje del turbo tiene holgura y pasa aceite al intercooler.", "TALLER", "aceleracion_caliente", "humo_azul_turbo|consumo_aceite_1l_300km|aceite_en_intercooler", "desgaste_anillos", "", "NO", "SI", "Consumo de aceite por desgaste de anillos o retenes", "L2 sellos de turbo pasados de aceite vs aros de pistón.")
    agregar("G15-L2-08", CLASE_15, "L2", "Al acelerar fuerte en subida silva como si tuviera una manguera suelta y el carro no avansa rapido echando humo negro oscuro por el escape.", "ERROR_ORTOGRAFICO", "subida_aceleracion", "silbido_manguera_suelta|humo_negro_oscuro", "falla_chispa", "", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L2 silbido de fuga y humo negro con ortografía informal.")
    agregar("G15-L2-09", CLASE_15, "L2", "Prueba de hermeticidad con máquina de humo a 1.0 bar demostró fuga activa en el acople rápido tipo bayoneta de la entrada del intercooler por sello gastado.", "TECNICO", "prueba_humo_1bar", "fuga_acople_bayoneta_intercooler|sello_gastado", "falla_valvula_alivio", "", "NO", "NO", "", "L2 O-ring de acople bayoneta soplado.")
    agregar("G15-L2-10", CLASE_15, "L2", "El motor tironea al exigir el turbo porque la mezcla se enriquece bruscamente al perder aire comprimido por una abrazadera floja en el tubo de carga.", "TALLER", "carga_turbo", "tironeo_mezcla_rica|aire_perdido_abrazadera_floja", "mezcla_pobre", "", "NO", "SI", "Falla en sensor de oxigeno o mezcla rica", "L2 mezcla rica por fuga post-MAF vs sensor de oxígeno.")
    agregar("G15-L2-11", CLASE_15, "L2", "Buenas, el carro pierde fuerza y silba como tetera caliente cuando acelero. Revisé abajo y la manguera negra gruesa está abierta por la mitad.", "WHATSAPP", "aceleracion", "silbido_tetera_caliente|manguera_abierta_mitad", "falla_transmision", "", "NO", "NO", "", "L2 silbido de tetera por raja en manguera de turbo.")
    agregar("G15-L2-12", CLASE_15, "L2", "El turbo aúlla muy fuerte desde las 1500 rpm; al soltar el conducto de admisión se encontró la propela del compresor con los álabes doblados por ingreso de cuerpo extraño.", "TECNICO", "inspeccion_alabes", "aullido_turbo_1500rpm|alabes_compresor_doblados_fOD", "fuga_manguera", "", "NO", "NO", "", "L2 daño por cuerpo extraño (FOD) en álabes de compresor.")
    agregar("G15-L2-13", CLASE_15, "L2", "Pérdida de potencia en carretera acompañada de soplido de viento en el habitáculo; la manguera acodada del intercooler se hinchó y reventó por fatiga.", "COTIDIANO", "carretera", "soplido_viento_habitaculo|manguera_acodada_reventada", "falla_compresor_ac", "", "NO", "NO", "", "L2 manguera acodada reventada en carretera.")
    agregar("G15-L2-14", CLASE_15, "L2", "Se genera código P0299 por falta de presión; el actuador neumático y la válvula N75 están perfectos, pero el intercooler tiene una fuga en el engrapado lateral.", "TECNICO", "diagnostico_p0299", "dtc_p0299|fuga_engrapado_intercooler|n75_conforme", "falla_actuador_vgt", "P0299", "NO", "SI", CLASE_14, "L2 intercooler fugando con válvula N75 conforme.")
    agregar("G15-L2-15", CLASE_15, "L2", "Al pisar el acelerador se escucha una fuga de aire continua en el frente y sale bocanada de humo negro; no hay fallas de encendido en bujías.", "COTIDIANO", "aceleracion", "fuga_aire_frente|humo_negro", "falla_bujias_encendido", "", "NO", "SI", "Falla en bujias o bobinas de encendido (misfire)", "L2 fuga de aire y humo negro descarta bujías.")

    # --- L3 (15 casos) ---
    agregar("G15-L3-01", CLASE_15, "L3", "El vehículo pierde potencia súbitamente al superar 2200 rpm bajo carga, emitiendo un soplido ensordecedor de aire comprimido en la zona delantera derecha y densa humareda negra por el escape con DTC P0299. La prueba de presurización con tapones de 2.5 pulgadas a 1.2 bar reveló una rotura de 6 cm en la manguera inferior de silicona del intercooler empapada en aceite. El actuador del turbo calibra y se desplaza con normalidad.", "TECNICO", "presurizacion_intercooler_1_2bar", "dtc_p0299|rotura_6cm_manguera_silicona|humo_negro_denso|soplido_ensordecedor", "falla_actuador_turbo", "P0299", "NO", "SI", CLASE_14, "L3 rotura de 6 cm en manguera inferior con actuador OK.")
    agregar("G15-L3-02", CLASE_15, "L3", "El turbocompresor emite un silbido agudo continuo similar a sirena policial desde 1400 rpm. Al desmontar el tubo de aspiración se constató juego axial de 2.2 mm y juego radial severo en el eje de la turbina, con rozamiento evidente de los álabes del compresor contra la caracola de aluminio produciendo limalla en el intercooler y consumo de aceite.", "TALLER", "inspeccion_holgura_turbo", "aullido_sirena_policial|juego_axial_2_2mm|roce_alabes_caracola", "fuga_manguera_aire", "", "NO", "SI", CLASE_14, "L3 turbocompresor con holgura axial de 2.2 mm y rozamiento.")
    agregar("G15-L3-03", CLASE_15, "L3", "En plena aceleración en cuesta se escuchó una detonación sorda bajo el capó seguida de pérdida del 60% de la potencia y soplido de escape de aire libre. En el taller se encontró la manguera superior de carga desacoplada del cuerpo de mariposa por rotura de la presilla de retención metálica. El motor de la mariposa y el actuador de turbo están en perfecto estado.", "TALLER", "aceleracion_cuesta", "manguera_desacoplada_mariposa|presilla_rota|perdida_60_potencia", "falla_cuerpo_mariposa", "", "NO", "SI", "Cuerpo de aceleracion o valvula IAC sucia", "L3 desacople de manguera en mariposa con cuerpo OK.")
    agregar("G15-L3-04", CLASE_15, "L3", "Código P0299 (Underboost) y P0101 (MAF Range). La lectura del caudalímetro registra 140 g/s pero el sensor MAP en el colector solo mide 0.4 bar de sobrealimentación. Al inyectar humo a 1.5 bar se detectó fisura en el tanque plástico lateral del intercooler producida por impacto frontal en carretera. No hay daño en la geometría del turbo.", "TECNICO", "prueba_humo_1_5bar", "dtc_p0299_p0101|fisura_tanque_plastico_intercooler|humo_fuga", "falla_geometria_turbo", "P0299", "NO", "SI", CLASE_14, "L3 P0299 y P0101 fisura en tanque lateral de intercooler.")
